/**
 * `WelcomeGlobe` - the world behind the Welcome sheet (feature 005, F12; owner decision Q-11;
 * UI-SPEC 7: "the sky with a globe turning behind (static under reduced motion)").
 *
 * This is the APPROVED FALLBACK, a static composed globe, not a second live map: the first
 * screen of the app must not depend on `useMapboxReady()` or a Mapbox token (a missing token
 * would leave the picture's centrepiece blank), and AGENTS.md allows ONE `MapView`. It is a
 * `react-native-svg` drawing of Natural Earth country outlines projected once
 * (`features/auth/welcome-globe-data.ts`, generated by `scripts/build-welcome-globe.mjs`): the
 * sea, a soft highlight, the graticule, the land with its keylines, the picture's coral
 * countries (the visited fill and keyline), two coral arcs and one dashed amber arc over a
 * white casing, and three dots. Every colour is a `GlobeColors` / `GlobeStyle` token of the
 * active light or dark lighting, the ones the live globe is gated on.
 *
 * Because it is drawn once and never moves there is no timer, no frame loop and nothing to stop
 * for reduced motion, a background app or a hidden screen (`idleSpinAllowed` has nothing to
 * gate): it is the still frame the spec asks for under reduced motion, for everyone. The
 * turning of the live Home globe is `useIdleSpin`, and a live globe here is a follow-up if the
 * owner wants the motion (device check, as-built note).
 *
 * It is decoration: hidden from assistive technology with its content, takes no touch, and
 * shows no traveller data (the arcs and dots are an illustration, never a trip).
 *
 * The box is a circle of radius `0.654 x width` (the pictured 255 dp at 390 dp), centred on
 * the screen, its top edge at `top`; the sheet covers its lower part.
 */
import { View } from 'react-native';
import Svg, {
  Circle,
  ClipPath,
  Defs,
  G,
  Path,
  RadialGradient,
  Stop,
} from 'react-native-svg';

import { GlobeColors, GlobeStyle } from '@/constants/theme';
import { useAppearance } from '@/hooks/use-appearance';
import {
  WELCOME_GLOBE,
  WELCOME_GLOBE_BOX,
  WELCOME_GLOBE_RADIUS,
} from '@/features/auth/welcome-globe-data';

/** The globe's radius as a fraction of the screen width: 255 dp on 390. */
export const WELCOME_GLOBE_RADIUS_RATIO = 255 / 390;

const CENTRE = WELCOME_GLOBE_BOX / 2;
const HIDDEN = {
  accessibilityElementsHidden: true,
  importantForAccessibility: 'no-hide-descendants',
} as const;

export type WelcomeGlobeProps = {
  /** The width of the screen, in dp. */
  width: number;
  /** Where the top of the disc is, in dp from the top of the screen. */
  top: number;
};

type Pin = readonly [number, number];

function Dot({ at, fill, ring }: { at: Pin; fill: string; ring: string }) {
  return (
    <>
      <Circle cx={at[0]} cy={at[1]} r={17} fill={ring} />
      <Circle cx={at[0]} cy={at[1]} r={11} fill={fill} />
    </>
  );
}

export function WelcomeGlobe({ width, top }: WelcomeGlobeProps) {
  const { theme } = useAppearance();
  const colours = GlobeColors[theme];
  const style = GlobeStyle[theme];
  const size = 2 * WELCOME_GLOBE_RADIUS_RATIO * width;
  const { arcs, pins } = WELCOME_GLOBE;

  return (
    <View
      testID="welcome-globe"
      pointerEvents="none"
      {...HIDDEN}
      style={{
        position: 'absolute',
        left: (width - size) / 2,
        top,
        width: size,
        height: size,
      }}>
      <Svg
        width={size}
        height={size}
        viewBox={`0 0 ${WELCOME_GLOBE_BOX} ${WELCOME_GLOBE_BOX}`}>
        <Defs>
          <ClipPath id="welcome-disc">
            <Circle cx={CENTRE} cy={CENTRE} r={WELCOME_GLOBE_RADIUS} />
          </ClipPath>
          <RadialGradient id="welcome-halo" cx="50%" cy="50%" r="50%">
            <Stop offset="0.92" stopColor={style.atmosphere.color} stopOpacity={0.55} />
            <Stop offset="1" stopColor={style.atmosphere.color} stopOpacity={0} />
          </RadialGradient>
          <RadialGradient id="welcome-light" cx="30%" cy="68%" r="55%">
            <Stop offset="0" stopColor={colours.casing} stopOpacity={0.55} />
            <Stop offset="1" stopColor={colours.casing} stopOpacity={0} />
          </RadialGradient>
        </Defs>
        <Circle cx={CENTRE} cy={CENTRE} r={CENTRE} fill="url(#welcome-halo)" />
        <Circle cx={CENTRE} cy={CENTRE} r={WELCOME_GLOBE_RADIUS} fill={style.water} />
        <G clipPath="url(#welcome-disc)">
          <Circle
            cx={CENTRE}
            cy={CENTRE}
            r={WELCOME_GLOBE_RADIUS}
            fill="url(#welcome-light)"
          />
          <Path
            d={WELCOME_GLOBE.graticule}
            stroke={style.graticule}
            strokeOpacity={style.graticuleOpacity}
            strokeWidth={1.5}
            fill="none"
          />
          <Path
            d={WELCOME_GLOBE.land}
            fill={colours.land}
            stroke={style.adminBoundaries}
            strokeWidth={1.2}
          />
          <Path
            d={WELCOME_GLOBE.visited}
            fill={colours.visitedFill}
            stroke={colours.visitedKeyline}
            strokeWidth={2}
          />
          {[arcs.lisbonNewYork, arcs.lisbonLondon].map((d) => (
            <G key={d}>
              <Path
                d={d}
                stroke={colours.casing}
                strokeWidth={11}
                strokeOpacity={0.9}
                fill="none"
              />
              <Path
                d={d}
                stroke={colours.past}
                strokeWidth={5.5}
                strokeLinecap="round"
                fill="none"
              />
            </G>
          ))}
          <Path
            d={arcs.lisbonReykjavik}
            stroke={colours.casing}
            strokeWidth={11}
            strokeOpacity={0.9}
            fill="none"
          />
          <Path
            d={arcs.lisbonReykjavik}
            stroke={colours.planning}
            strokeWidth={5.5}
            strokeDasharray="16 9"
            fill="none"
          />
          <Dot at={pins.lisbon} fill={colours.active} ring={colours.casing} />
          <Dot at={pins.london} fill={colours.active} ring={colours.casing} />
          <Dot at={pins.reykjavik} fill={colours.planning} ring={colours.casing} />
        </G>
      </Svg>
    </View>
  );
}
